recipe(key='bravas',market='es',slug='patatas-bravas-freidora-aire',title='Patatas bravas en freidora de aire con salsa casera',category='entrantes-y-aperitivos',cuisine='Española',servings=4,prep=15,cook=35,rest=0,difficulty='Fácil',summary='Patatas bravas doradas en freidora de aire, con salsa de pimentón y caldo sin tomate. Una tapa para compartir, con tiempos por tanda y picante ajustable.',notes='Corta dados de 2 cm y usa una freidora de al menos 5 litros; si quedan amontonados, haz dos tandas y añade unos 25 minutos al total. La salsa lleva harina de trigo: contiene gluten. Usa caldo sin gluten y maicena solo con una adaptación de la salsa. No añadas el pimentón al aceite humeante. Guarda patatas y salsa separadas en la nevera a 4 °C o menos hasta 2 días; recalienta bien. La textura crujiente es mejor recién hecha.',ingredients=[['patatas peladas','800','g'],['aceite de oliva: 15 g para patatas y 20 g para salsa','35','g'],['cebolla','100','g'],['ajo','5','g'],['harina de trigo','10','g'],['pimentón dulce','4','g'],['pimentón picante','1','g'],['caldo de verduras listo para usar','250','ml'],['vinagre de vino','10','ml'],['sal','3','g']],steps=[['Corta las patatas','Pela 800 g de patatas y corta dados de 2 cm. Enjuaga y seca muy bien con un paño limpio; la humedad dificulta el dorado.'],['Prepara la freidora','Precalienta a 190 °C durante 3 minutos, si lo requiere el aparato. Mezcla las patatas con 15 g de aceite y 2 g de sal.'],['Cocina sin amontonar','Extiende las patatas con espacio entre ellas. Cocina a 190 °C durante 20 minutos, agitando la cesta a mitad. Si no caben, haz dos tandas.'],['Pocha cebolla y ajo','Mientras se cocinan, pica 100 g de cebolla y 5 g de ajo. Ablanda la cebolla con 20 g de aceite 8 minutos; añade el ajo 1 minuto.'],['Tuesta harina y pimentón','Incorpora 10 g de harina y remueve 1 minuto. Aparta del fuego, añade ambos pimentones y mezcla unos segundos sin quemarlos.'],['Termina la salsa','Añade poco a poco 250 ml de caldo, batiendo. Hierve suave 5 minutos; agrega vinagre y 1 g de sal. Tritura hasta obtener una salsa lisa.'],['Comprueba el dorado','Sube la freidora a 200 °C y cocina 3–5 minutos más. Las patatas deben estar tiernas por dentro y doradas por fuera; prolonga si hace falta.'],['Sirve con la salsa','Reparte en cuatro porciones de tapa y añade la salsa caliente justo antes de comer. Lleva la salsa sobrante a la mesa en un cuenco.']],faq=[['¿Se puede hacer sin tomate?','Sí. Esta salsa se liga con harina y caldo y toma su color del pimentón; existen también otras versiones con tomate.'],['¿Por qué quedan blandas?','Suele haber exceso de humedad o demasiadas patatas en la cesta. Seca bien y cocina por tandas sin amontonar.'],['¿Cómo reduzco el picante?','Sustituye el gramo de pimentón picante por otro gramo de pimentón dulce. Mantén el resto de cantidades.']],nutrition_terms=['Potatoes, flesh and skin, raw','Oil, olive','Onions, raw','Garlic, raw','Wheat flour, white, all-purpose','Spices, paprika','Spices, paprika','Soup, vegetable broth','Vinegar, red wine','Salt, table'],nutrition_grams=[800,35,100,5,10,4,1,250,10,3],pantry_slugs=['papa','aceite-de-oliva','cebolla','ajo','harina-de-trigo',None,None,None,None,'sal'],sources=['https://www.elespanol.com/cocinillas/recetas/20260609/chefs-madrilenos-coinciden-mejor-salsa-brava-no-lleva-tomate-ponle-caldo-jamon-harina-pimenton-cebolla/1003744278725_0.html','https://recetas.osterlatinoamerica.com/recipes/10122/patatas_bravas'],scenes=['Peeled raw potato cubes exactly 2cm on wooden board, clean dry towel and knife, no sauce yet.','Cream bowl of raw potato cubes lightly coated in olive oil, black air fryer basket alongside, no sauce.','Open black air fryer drawer with potato cubes partly cooked, pale golden, evenly spread, no sauce.','Small stainless saucepan with finely chopped onion softening in olive oil, a small dish of minced garlic alongside, no red sauce yet.','Same stainless saucepan of soft onion with flour and deep red paprika added, off the burner; wooden spoon, no tomato.','Same saucepan containing smooth orange-red paprika gravy, a stick blender resting beside the pan, small clear jug of vegetable broth behind.','Open black air fryer drawer of crisp deep golden potato cubes, no sauce added, golden edges not burnt.','Cream ceramic serving platter of golden 2cm potato cubes drizzled with smooth orange-red brava sauce, small cream bowl of extra sauce alongside, no mayonnaise, no herbs.'])
recipe(key='pizza',market='en',slug='pizza-beans-alubias-gratinadas',title='Pizza beans: alubias blancas con tomate y mozzarella',category='platos-principales',cuisine='Estadounidense de inspiración italiana',servings=4,prep=10,cook=25,rest=5,difficulty='Fácil',summary='Pizza beans en una sartén: alubias blancas cocidas, salsa de tomate y mozzarella gratinada. Una cena sencilla de despensa, lista en 40 minutos y sin masa.',notes='Usa alubias de conserva ya cocidas y escurridas, nunca judías secas crudas. Necesitas una sartén de 26 cm apta para horno; en otro caso pasa la mezcla a una fuente antes de gratinar. Contiene leche. El pan de acompañamiento no forma parte de la receta ni del cálculo nutricional. Refrigera las sobras antes de 2 horas, a 4 °C o menos, durante un máximo de 3 días; recalienta hasta que estén bien calientes en el centro.',ingredients=[['alubias blancas cocidas de conserva, escurridas','700','g'],['tomate triturado sin azúcar añadido','500','g'],['cebolla','100','g'],['ajo','6','g'],['aceite de oliva','20','g'],['tomate concentrado','20','g'],['mozzarella rallada','150','g'],['orégano seco','2','g'],['sal','2','g']],steps=[['Escurre y prepara','Enjuaga y escurre 700 g de alubias cocidas. Pica cebolla y ajo. Precalienta el horno a 220 °C, con calor arriba y abajo.'],['Ablanda la cebolla','Calienta 20 g de aceite en una sartén de 26 cm apta para horno. Cocina la cebolla a fuego medio 6 minutos, removiendo.'],['Añade ajo y concentrado','Incorpora el ajo y 20 g de tomate concentrado. Remueve 1 minuto para que desprendan aroma sin quemarse.'],['Reduce el tomate','Añade 500 g de tomate triturado, 1 g de orégano y 2 g de sal. Cocina destapado 10 minutos, hasta que espese ligeramente.'],['Incorpora las alubias','Agrega las alubias escurridas y mezcla con cuidado para no romperlas. Calienta 3 minutos; la salsa debe envolverlas sin quedar seca.'],['Cubre con mozzarella','Apaga el fuego. Distribuye 150 g de mozzarella y el gramo de orégano restante por encima, sin mezclar el queso con la salsa.'],['Gratina en el horno','Hornea 5–8 minutos a 220 °C, hasta fundir y dorar el queso. Usa guantes: el mango de la sartén también estará caliente.'],['Reposa y sirve','Deja reposar 5 minutos sobre un salvamanteles. Sirve cuatro porciones calientes, con las alubias enteras y el queso gratinado por encima.']],faq=[['¿Puedo usar alubias secas?','Solo después de remojarlas y cocinarlas por completo siguiendo el envase. Pesa 700 g ya cocidas y escurridas; ese tiempo adicional no está incluido.'],['¿Sirven garbanzos?','Sí, cocidos y escurridos, aunque cambia la textura y la estimación nutricional. La versión principal utiliza alubias blancas.'],['¿Se puede hacer sin horno?','Puedes tapar la sartén a fuego bajo hasta fundir el queso, pero no se formará la superficie dorada del gratinado.']],nutrition_terms=['Beans, white, mature seeds, canned','Tomatoes, crushed, canned','Onions, raw','Garlic, raw','Oil, olive','Tomato products, canned, paste','Cheese, mozzarella, whole milk','Spices, oregano','Salt, table'],nutrition_grams=[700,500,100,6,20,20,150,2,2],pantry_slugs=[None,'tomate','cebolla','ajo','aceite-de-oliva',None,'queso-mozzarella',None,'sal'],sources=['https://www.foodandwine.com/pizza-beans-high-fiber-trend-12139000'],scenes=[])
recipe(key='spekulatius',market='de',slug='vasitos-manzana-spekulatius',title='Vasitos de manzana y Spekulatius sin horno',category='postres',cuisine='Alemana de inspiración navideña',servings=6,prep=25,cook=10,rest=140,difficulty='Fácil',summary='Postre de manzana, galletas Spekulatius y crema de yogur y nata en seis vasitos. Sin huevo ni horno, con las capas y el tiempo de enfriado explicados.',notes='Usa galletas Spekulatius especiadas, no crema para untar. Contiene leche y trigo; revisa las galletas por posibles frutos secos. Enfría la manzana completamente antes de montar para que la nata no pierda volumen. Los 140 minutos de reposo incluyen 20 minutos para enfriar la compota y 2 horas de nevera. Guarda tapado a 4 °C o menos y consume en 2 días. Añade las migas finales al servir para que sigan crujientes.',ingredients=[['manzanas peladas y sin corazón','500','g'],['galletas Spekulatius','150','g'],['yogur griego natural entero','300','g'],['nata para montar, 35 % de grasa, fría','200','g'],['azúcar: 20 g para manzana y 20 g para crema','40','g'],['agua','40','ml'],['zumo de limón','15','ml'],['canela molida','1','g']],steps=[['Corta la manzana','Corta 500 g de manzana limpia en dados pequeños. Ponla en un cazo con 40 ml de agua, limón, canela y 20 g de azúcar.'],['Cocina la compota','Tapa y cocina a fuego medio-bajo 8–10 minutos, removiendo. La manzana debe estar tierna, con algunos dados enteros; destapa al final si sobra líquido.'],['Enfría por completo','Extiende la compota en un recipiente poco profundo y deja templar unos 20 minutos. Después refrigera mientras preparas la crema; no la uses caliente.'],['Rompe las galletas','Tritura groseramente 150 g de Spekulatius dentro de una bolsa alimentaria. Reserva 30 g de migas secas para decorar al servir.'],['Monta la nata','Bate 200 g de nata bien fría con los 20 g restantes de azúcar hasta obtener picos suaves. No sigas batiendo hasta que se corte.'],['Prepara la crema','Remueve 300 g de yogur hasta alisarlo. Incorpora la nata con una espátula, suavemente y en dos tandas, conservando el aire.'],['Monta y refrigera','Reparte los 120 g de migas, la compota fría y la crema entre seis vasos de 200 ml. Tapa y refrigera durante 2 horas.'],['Termina los vasitos','Reparte los 30 g de migas reservadas por encima justo antes de servir. Sirve frío, un vaso por persona.']],faq=[['¿Puedo prepararlo el día anterior?','Sí. Guarda los vasos tapados en la nevera y las migas finales en un recipiente seco; añádelas al servir.'],['¿Qué uso si no encuentro Spekulatius?','Galletas especiadas de canela o jengibre. El sabor y los nutrientes serán distintos; evita añadir más canela sin probar.'],['¿Por qué queda líquida la crema?','La compota caliente, el yogur poco espeso o la nata sin montar pueden aflojarla. Usa todo frío y respeta las 2 horas de nevera.']],nutrition_terms=['Apples, raw, without skin','Cookies, gingersnaps','Yogurt, Greek, plain, whole milk','Cream, fluid, heavy whipping','Sugars, granulated','Water, tap','Lemon juice, raw','Spices, cinnamon'],nutrition_grams=[500,150,300,200,40,40,15,1],pantry_slugs=['manzana',None,'yogur-griego','crema-de-leche','azucar','agua','limon','canela'],sources=['https://www.oetker.de/inspiration/anlaesse/weihnachten/spekulatius','https://www.lieblingszwei.de/spekulatius-apfel-dessert/'],scenes=['Peeled apple diced into small cubes on light wood board, cream bowl of sugar, small lemon half, small cinnamon dish, no dessert glasses.','Stainless small saucepan of soft pale golden apple cubes simmering gently in a little juice with cinnamon, no cream or cookies.','Shallow cream ceramic dish of cooled cooked diced apple compote, no steam, spoon alongside, no cream.','Crumbled brown spiced Spekulatius cookies in cream bowl, a few plain molded rectangular spiced cookies alongside, no brand or letters.','Stainless bowl of freshly whipped white cream with soft peaks on whisk, cream carton absent, no fruit.','Cream ceramic mixing bowl of thick pale white Greek yogurt and whipped cream being folded with silicone spatula, no fruit or cookie crumbs.','Exactly six straight clear 200ml glasses, layers of brown cookie crumbs bottom, pale golden cooked apple middle, fluffy white cream top, plain transparent lids, no final crumb garnish.','Exactly six clear 200ml dessert glasses with brown cookie crumb base, generous golden diced cooked apple middle, fluffy white yogurt cream top dusted with reserved brown cookie crumbs, no mint, no berries, no whole cookies sticking out.'])
recipe(key='tartiflette',market='fr',slug='tartiflette-reblochon-patatas',title='Tartiflette de patatas con reblochon y bacon',category='platos-principales',cuisine='Francesa, Saboya',servings=6,prep=20,cook=50,rest=5,difficulty='Fácil',summary='Tartiflette casera con patatas tiernas, cebolla, bacon y reblochon gratinado. Una fuente para seis porciones, con instrucciones para conservar la corteza del queso.',notes='Usa patatas de carne firme y reblochon; camembert permite una adaptación si no lo consigues, aunque cambia el sabor. Contiene leche. El bacon y el queso aportan sal: prueba antes de añadir más. Cocina el vino 3 minutos; eso no garantiza eliminar todo el alcohol. Puedes sustituirlo por agua, con otro perfil de sabor. Guarda las sobras antes de 2 horas a 4 °C o menos hasta 3 días y recalienta bien. Usa una fuente de unos 25 × 20 cm.',ingredients=[['patatas peladas','1000','g'],['queso reblochon','450','g'],['bacon ahumado en dados','180','g'],['cebolla','200','g'],['vino blanco seco','100','ml'],['ajo','5','g'],['pimienta negra molida','1','g']],steps=[['Corta y cuece las patatas','Corta las patatas en rodajas de 8 mm. Ponlas en agua fría, lleva a ebullición y cocina 10–12 minutos, hasta que estén casi tiernas.'],['Escurre con cuidado','Escurre y deja evaporar el agua durante 5 minutos. Precalienta el horno a 200 °C, con calor arriba y abajo.'],['Dora el bacon','Pon el bacon en una sartén amplia sin aceite. Cocina a fuego medio 5 minutos, removiendo, hasta que suelte grasa y comience a dorar.'],['Añade cebolla y vino','Agrega la cebolla en tiras y cocina 8 minutos. Vierte 100 ml de vino y hierve 3 minutos, hasta reducir bastante el líquido.'],['Prepara el queso','Corta el reblochon por su grosor, conservando la corteza. Trocea una mitad y divide la otra en dos piezas para cubrir la fuente.'],['Monta la fuente','Frota la fuente con el ajo partido. Mezcla patatas, bacon, cebolla, pimienta y queso troceado. Coloca encima las piezas restantes, con la corteza hacia arriba.'],['Hornea hasta gratinar','Hornea 20–25 minutos a 200 °C, hasta que las patatas estén tiernas, el queso fundido y la superficie dorada. Protege con papel si se tuesta demasiado.'],['Reposa y sirve','Deja reposar 5 minutos fuera del horno. Reparte seis porciones calientes, recogiendo patatas, queso y bacon de toda la profundidad.']],faq=[['¿Se retira la corteza del reblochon?','No en esta versión. Mantén la corteza comestible y coloca las piezas de arriba con la corteza hacia arriba para gratinar.'],['¿Se puede sustituir el vino?','Sí, por 100 ml de agua. Será una adaptación; la receta con vino no garantiza ausencia de alcohol tras una cocción corta.'],['¿Sirve otro queso?','Camembert es una sustitución accesible, pero la tartiflette de referencia se prepara con reblochon y su sabor es distinto.']],nutrition_terms=['Potatoes, flesh and skin, raw','Cheese, camembert','Pork, cured, bacon, unprepared','Onions, raw','Alcoholic beverage, wine, table, white','Garlic, raw','Spices, pepper, black'],nutrition_grams=[1000,450,180,200,100,5,1],pantry_slugs=['papa',None,'tocineta','cebolla','vino-blanco','ajo','pimienta-negra'],sources=['https://www.reblochon.fr/nos-recettes/tartiflette-reblochon-de-savoie/','https://www.fromagesdesavoie.fr/recettes/tartiflette/'],scenes=['Peeled firm potatoes sliced into 8mm rounds on a wooden board, stainless pot of water nearby, no cheese.','Colander of parboiled potato rounds draining, pale and intact, stainless pot beneath, no cheese or meat yet.','Stainless frying pan of small smoked bacon cubes beginning to brown and release fat, no potatoes or cheese.','Same pan with bacon and softened thinly sliced onion, a small amount of white wine reducing, no cheese.','One round Reblochon cheese with natural peach-white rind, split horizontally into two thin wheels; half cut into chunks and half kept in two semicircles on wooden board, no labels.','Cream rectangular 25x20cm baking dish of potato slices, onion and bacon with small cheese chunks between, two raw half-wheel pieces of reblochon on top rind facing UP, ready for oven.','Same cream rectangular dish of bubbling baked tartiflette, golden peach-colored cheese rind melted over potatoes, visible onion and bacon at edges, oven mitt nearby.','Cream rectangular dish of golden tartiflette with tender potato rounds, bacon and molten reblochon, one portion lifted onto a cream plate, cheese stretching modestly, no garnish, no salad.'])
recipe(key='zucca',market='it',slug='pasta-horno-calabaza-ricotta',title='Pasta al horno con calabaza y ricotta, sin bechamel',category='pastas',cuisine='Italiana',servings=4,prep=15,cook=50,rest=5,difficulty='Fácil',summary='Pasta corta al horno con crema de calabaza asada, ricotta y mozzarella. Gratinada sin bechamel, con cantidades para cuatro porciones y consejos para que no se reseque.',notes='Pesa 600 g de calabaza ya pelada y sin semillas; una variedad de pulpa firme funciona mejor. Usa una fuente de unos 24 × 20 cm. Contiene trigo y leche. La pasta se hierve menos tiempo porque termina en el horno. El agua reservada ajusta la salsa según la humedad de la calabaza. Guarda refrigerada antes de 2 horas, a 4 °C o menos, hasta 3 días; añade un poco de agua antes de recalentar bien.',ingredients=[['pasta corta seca, tipo rigatoni','320','g'],['calabaza pelada y sin semillas','600','g'],['ricotta','250','g'],['mozzarella rallada','120','g'],['queso parmesano rallado','30','g'],['aceite de oliva','20','g'],['ajo','5','g'],['sal','5','g'],['pimienta negra molida','1','g'],['agua reservada de cocción de la pasta','150','ml']],steps=[['Prepara la calabaza','Precalienta el horno a 200 °C. Corta 600 g de calabaza en dados de 2 cm y mezcla con aceite, ajo picado, 2 g de sal y pimienta.'],['Asa hasta ablandar','Extiende en una bandeja y asa 25–30 minutos, removiendo una vez. Debe estar tierna y dorada en algunos bordes, sin quemarse.'],['Cuece la pasta','Hierve la pasta en agua con los 3 g de sal restantes. Escurre 2 minutos antes del tiempo del envase y reserva 150 ml del agua.'],['Tritura la salsa','Tritura la calabaza asada con ricotta y 100 ml del agua reservada. Debe quedar una crema suave que fluya; añade el resto del agua si hace falta.'],['Mezcla con la pasta','Junta pasta y salsa en un bol grande. Incorpora 60 g de mozzarella y 15 g de parmesano, repartiendo la crema por todos los tubos.'],['Prepara el gratinado','Vierte en una fuente de unos 24 × 20 cm. Cubre con los 60 g de mozzarella y 15 g de parmesano restantes.'],['Hornea la fuente','Hornea 15–20 minutos a 200 °C hasta que los bordes burbujeen y el queso se dore. La pasta debe permanecer cremosa bajo la superficie.'],['Reposa y reparte','Espera 5 minutos fuera del horno y sirve cuatro porciones. Recoge un poco del gratinado y de la crema de la base en cada plato.']],faq=[['¿Se puede preparar antes?','Puedes montar la fuente y refrigerarla tapada hasta el día siguiente. Hornea desde fría más tiempo, comprobando que el centro quede bien caliente.'],['¿Por qué se seca?','La calabaza puede tener poca agua o la pasta estar demasiado cocida. Al montar, la salsa debe quedar algo más fluida de lo que servirías en sartén.'],['¿Lleva bechamel?','No. La ricotta y la calabaza trituradas forman la crema; el agua de cocción ayuda a ligarla y ajustar su espesor.']],nutrition_terms=['Pasta, dry, unenriched','Pumpkin, raw','Cheese, ricotta, whole milk','Cheese, mozzarella, whole milk','Cheese, parmesan, hard','Oil, olive','Garlic, raw','Salt, table','Spices, pepper, black','Water, tap'],nutrition_grams=[320,600,250,120,30,20,5,5,1,150],pantry_slugs=['pasta','calabaza',None,'queso-mozzarella','queso-parmesano','aceite-de-oliva','ajo','sal','pimienta-negra','agua'],sources=['https://www.lacucinaitaliana.it/news/cucina/pasta-e-zucca/','https://blog.giallozafferano.it/pelledipollo/ricetta-pasta-al-forno-con-zucca-e-ricotta/'],scenes=['Peeled orange pumpkin cut into 2cm cubes, small dish of olive oil and minced garlic beside a rimmed metal baking tray, no pasta or cheese.','Rimmed metal tray of roasted orange pumpkin cubes, lightly browned edges and tender centers, no pasta.','Stainless pot with cooked rigatoni pasta, strainer nearby and a small heatproof jug of starchy cooking water, no orange sauce.','Blender jug of smooth orange pumpkin and white ricotta cream, ricotta bowl beside, no pasta mixed yet.','Large cream mixing bowl of ridged rigatoni coated in smooth pale orange pumpkin ricotta sauce, with some white shredded mozzarella being folded in.','Cream rectangular 24x20cm baking dish of rigatoni in orange pumpkin sauce topped with unmelted grated mozzarella and parmesan, ready for oven.','Same cream rectangular baking dish with golden gratinated pumpkin rigatoni, bubbling orange creamy edges, oven mitt beside.','Cream rectangular baking dish of golden baked rigatoni in pumpkin ricotta sauce, one portion served on a cream shallow plate showing orange creamy sauce beneath lightly browned cheese, no green garnish.'])
recipe(key='seiro',market='ja',slug='cerdo-repollo-vapor-seiro',title='Cerdo y repollo al vapor en seiro con salsa de sésamo',category='platos-principales',cuisine='Japonesa de inspiración casera',servings=2,prep=15,cook=18,rest=3,difficulty='Fácil',summary='Láminas finas de cerdo y repollo cocinadas al vapor en seiro, con zanahoria y salsa de sésamo y soja. Incluye cómo montar las capas y comprobar la cocción.',notes='Usa lomo de cerdo cortado en láminas de 2 mm, no carne picada ni láminas gruesas. Necesitas una vaporera de bambú de unos 24 cm compatible con la olla, o una vaporera metálica con tapa. Sigue las indicaciones de su fabricante. Contiene soja, sésamo y normalmente trigo por la salsa de soja. No tapes todos los orificios con papel: debe circular el vapor. No dejes que la olla se seque. Guarda las sobras antes de 2 horas a 4 °C o menos hasta 2 días y recalienta por completo.',ingredients=[['lomo de cerdo en láminas de 2 mm','250','g'],['repollo limpio','400','g'],['zanahoria pelada','100','g'],['salsa de soja','25','g'],['tahini o pasta de sésamo sin azúcar','25','g'],['vinagre de arroz','15','ml'],['agua para la salsa','20','ml'],['azúcar','5','g'],['jengibre fresco','5','g']],steps=[['Prepara la vaporera','Humedece la vaporera de bambú según el fabricante. Llena la olla con agua sin que toque su base y lleva a hervor; comprueba que encaje estable.'],['Corta las verduras','Corta el repollo en trozos de 4 cm y la zanahoria en láminas de 2 mm. Reserva las hojas más grandes para cubrir parcialmente la base.'],['Separa el cerdo','Separa las láminas de cerdo para que no formen bloques. Corta las piezas largas por la mitad y mantén la carne fría hasta montar.'],['Distribuye en capas ligeras','Coloca hojas de repollo en la base dejando huecos. Añade zanahoria y el resto del repollo, intercalando el cerdo desplegado sin formar una capa compacta.'],['Cocina al vapor','Pon la vaporera sobre la olla hirviendo, tapa y cocina 15–18 minutos. Mantén vapor constante y añade agua caliente a la olla si baja demasiado el nivel.'],['Mezcla la salsa','Mezcla tahini, soja, vinagre, 20 ml de agua, azúcar y jengibre rallado hasta que quede una salsa fluida. Usa utensilios sin contacto con carne cruda.'],['Comprueba y deja reposar','Comprueba al menos 63 °C en la zona más gruesa del cerdo con termómetro. Si falta, sigue cocinando. Retira del vapor y deja reposar tapado 3 minutos.'],['Sirve con salsa aparte','Abre la tapa alejándola del rostro para evitar el vapor. Sirve dos porciones de cerdo y verduras con la salsa de sésamo aparte.']],faq=[['¿Puedo usar una vaporera metálica?','Sí, con tapa, base estable y agua sin tocar los alimentos. El tiempo puede variar: comprueba la cocción del cerdo con termómetro.'],['¿Puedo usar pollo?','Es otra adaptación y requiere al menos 74 °C en el centro. No apliques el punto de 63 °C del cerdo al pollo.'],['¿Por qué no se cocina uniformemente?','La carne amontonada o el papel tapando los huecos impiden circular el vapor. Distribuye láminas separadas y cocina por tandas si hace falta.']],nutrition_terms=['Pork, fresh, loin, whole, separable lean and fat, raw','Cabbage, raw','Carrots, raw','Soy sauce made from soy and wheat','Seeds, sesame butter, tahini','Vinegar, distilled','Water, tap','Sugars, granulated','Ginger root, raw'],nutrition_grams=[250,400,100,25,25,15,20,5,5],pantry_slugs=[None,'repollo','zanahoria','salsa-de-soja',None,None,'agua','azucar','jengibre'],sources=['https://news.livedoor.com/article/detail/17734063/','https://park.ajinomoto.co.jp/recipe/card/708752/'],scenes=['Empty damp round bamboo seiro steamer 24cm seated securely over stainless pot with water below not touching basket, lid beside, no food yet.','Fresh pale green cabbage cut into 4cm pieces and thin orange carrot slices on light wooden board, no meat.','Thin raw pork loin slices about 2mm separated on a dedicated cream plate, no cutting knife touching vegetables, no cooked food.','Bamboo seiro of cabbage and thin carrot slices loosely interleaved with uncooked pink pork loin slices unfolded, gaps for steam, no sauce.','Same bamboo seiro covered with woven bamboo lid over gently boiling stainless pot, light steam escaping at edges, no excessive water near table.','Small cream bowl of smooth beige sesame tahini soy dressing with grated ginger, whisk nearby and generic tiny dishes of soy sauce and rice vinegar, no raw pork.','Open bamboo seiro with fully cooked pale opaque pork slices and tender pale green cabbage, orange carrot, digital food thermometer probe inserted in folded thickest pork with display turned away, no pink raw meat.','Open round bamboo seiro filled with fully cooked pale opaque pork loin slices over tender cabbage and thin orange carrot, small cream bowl of beige sesame dipping sauce next to basket, no rice, no sesame seeds garnish, no green onions.'])
recipe(key='morango',market='pt',slug='morango-cravejado',title='Morango cravejado: fresas con brigadeiro y cobertura crujiente',category='postres',cuisine='Brasileña',servings=10,prep=35,cook=25,rest=160,difficulty='Media',summary='Morango cravejado brasileño: fresas enteras envueltas en brigadeiro blanco y cobertura blanca con trocitos de caramelo rojo. Receta para diez unidades, con enfriados incluidos.',notes='Elige diez fresas firmes de unos 25 g, ya limpias y completamente secas. Usa cobertura blanca de repostería que no requiera templado; el chocolate blanco puro necesita su propio templado y no es intercambiable en el proceso. Contiene leche y puede contener soja. El caramelo a 150 °C quema: usa termómetro y utensilios secos, sin tocarlo hasta que esté frío. Guarda en nevera a 4 °C o menos y consume en 24 horas; la fruta suelta agua y el caramelo pierde crujiente. No se establece una vida útil comercial.',ingredients=[['fresas firmes limpias y muy secas, unas 10','250','g'],['leche condensada azucarada','395','g'],['nata líquida','100','g'],['leche entera en polvo','30','g'],['mantequilla','10','g'],['azúcar','100','g'],['agua','40','ml'],['vinagre blanco','5','ml'],['colorante alimentario rojo hidrosoluble, dosis según fabricante','1','g'],['cobertura blanca de repostería sin necesidad de templado','250','g']],steps=[['Limpia y seca las fresas','Lava las fresas y sécalas completamente con papel limpio. Retira las hojas sin perforar la pulpa. Mantén refrigeradas y prepara una bandeja con papel de horno.'],['Cocina el brigadeiro','Mezcla leche condensada, nata, leche en polvo y mantequilla en un cazo. Cocina a fuego medio-bajo 10–15 minutos, removiendo, hasta que se separe del fondo al inclinar.'],['Enfría la masa','Pasa a un recipiente poco profundo, cubre la superficie y deja templar 20 minutos. Refrigera 2 horas o hasta obtener una masa fría que pueda moldearse.'],['Prepara el caramelo rojo','Pon azúcar, agua, vinagre y colorante en un cazo seco. Mezcla antes de calentar; después hierve sin remover hasta 150 °C, controlando con termómetro.'],['Enfría y rompe el caramelo','Vierte con cuidado una capa fina sobre un tapete de silicona resistente al calor. Enfría por completo unos 20 minutos. Rompe dentro de una bolsa en trocitos pequeños.'],['Envuelve las fresas','Divide el brigadeiro frío en diez porciones iguales. Aplana cada una con manos limpias ligeramente humedecidas y envuelve una fresa seca; cierra sin dejar huecos. Refrigera.'],['Baña con cobertura','Derrite la cobertura siguiendo su envase, sin sobrecalentar. Cuando esté fluida y tibia, incorpora el caramelo frío. Baña cada fresa con un tenedor, escurre y coloca sobre papel.'],['Deja fijar y sirve','Deja fijar la cobertura según el envase y refrigera. Sirve diez unidades; corta una para mostrar fresa, brigadeiro y cubierta blanca con puntos rojos. Consume en 24 horas.']],faq=[['¿Es igual al morango do amor?','Comparte la fresa y el brigadeiro. Aquí el caramelo rojo va en trocitos dentro de la cobertura blanca, en lugar de formar una cáscara roja continua.'],['¿Por qué se humedece?','La fruta desprende agua y el azúcar absorbe humedad. Seca muy bien las fresas, no perfores su pulpa y prepara para consumir en 24 horas.'],['¿Puedo venderlo?','Calcula ingredientes, envase, energía, trabajo y mermas por unidad. Antes de vender, valida higiene, conservación y vida útil con los requisitos locales; esta receta no los certifica.']],nutrition_terms=['Strawberries, raw','Milk, canned, condensed, sweetened','Cream, fluid, heavy whipping','Milk, dry, whole','Butter, without salt','Sugars, granulated','Water, tap','Vinegar, distilled','coloring','Candies, white chocolate'],nutrition_grams=[250,395,100,30,10,100,40,5,1,250],pantry_slugs=['fresa','leche-condensada','crema-de-leche',None,'mantequilla','azucar','agua',None,None,None],sources=['https://www.cnnbrasil.com.br/curiosidades/morango-do-amor-cravejado-doce-que-viralizou-em-2025-ganha-nova-versao-ainda-mais-gourmet/','https://cozinhalegal.com.br/morango-cravejado/','https://www.receitasnestle.com.br/receitas/receita-morango-cravejado'],scenes=['Ten fresh firm whole strawberries with green tops removed carefully, fully dry on clean white kitchen paper, small cream tray, no chocolate yet.','Stainless saucepan with thick pale ivory condensed milk brigadeiro mixture being stirred with silicone spatula, mixture pulls from base, small cream bowls of milk powder and butter beside.','Shallow cream rectangular container of thick ivory brigadeiro covered directly on surface with transparent food film, cool and firm, no strawberries added yet.','Small stainless saucepan with boiling clear ruby-red sugar syrup, candy thermometer clipped safely with display turned away, dry utensils, no hands, no flame on table.','Thin ruby-red hardened caramel sheet broken into tiny jewel-like shards on heatproof silicone mat, small food-safe clear bag containing some crushed pieces, no strawberries yet.','Ten strawberries completely encased in smooth pale ivory brigadeiro coating, one cross-section shows whole red strawberry surrounded by ivory dough, on baking parchment, no outer chocolate yet.','Small bowl of melted white confectionery coating with tiny ruby-red caramel chips mixed through, a dipping fork holding an oval brigadeiro-coated strawberry partly dipped, no green leaves, safe dry setup.','Cream platter of ten oval white confectionery strawberry bonbons with small ruby-red caramel flecks embedded in white coating, one cut cleanly in half showing a red whole strawberry center, thick ivory brigadeiro middle and thin white speckled shell, no leaf garnish, no nuts.'])
